<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class QuizAnswer extends Model { use HasFactory; protected $fillable=['quiz_attempt_id','quiz_question_id','selected_option_id','boolean_answer','text_answer','is_correct','awarded_points','teacher_feedback','saved_at']; protected function casts():array{return['boolean_answer'=>'boolean','is_correct'=>'boolean','awarded_points'=>'decimal:2','saved_at'=>'datetime'];} public function attempt():BelongsTo{return $this->belongsTo(QuizAttempt::class,'quiz_attempt_id');} public function quizQuestion():BelongsTo{return $this->belongsTo(QuizQuestion::class);} public function selectedOption():BelongsTo{return $this->belongsTo(QuestionBankOption::class,'selected_option_id');} }
